window.MONSTER_CHUNK_40 = [{"name":"Weretiger","cr":4,"xp":1200,"race":"Human","classes":[{"class":"rogue","level":4}],"alignment":"NE","size":"Large","type":"humanoid","subtypes":["human","shapechanger"],"init":7,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+3 armor, +3 Dex, +5 natural, -1 size","hp":37,"hd":"4d8+16","hdvalue":4,"fort":4,"ref":7,"will":4,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"dr":"10/silver","speed":[{"type":"land","speed":30}],"melee":"bite +8 (2d6+6 plus grab and curse of lycanthropy), 2 claws +8 (1d8+6 plus grab)","ranged":"mwk dagger +6 (1d6+6/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +8, 1d8+6"},{"type":"sneak attack","details":"+2d6"}],"strength":23,"dexterity":16,"constitution":17,"intelligence":10,"wisdom":16,"charisma":8,"baseatk":3,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":23,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Climb","value":12},{"skill":"Handle Animal","value":3},{"skill":"Intimidate","value":6},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":7},{"skill":"Swim","value":2}],"languages":["Common"],"sq":[{"type":"change shape","details":"human, hybrid, and tiger; polymorph"},{"type":"lycanthropic empathy","details":"tigers and dire tigers"},{"type":"rogue talents","details":"bleeding attack +2, fast stealth"},{"type":"trapfinding","details":"+2"}],"environments":["any plains","any swamps"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This humanoid tiger has striped fur and a muscular, lanky frame. Its feline face has sharp fangs and slitted eyes.","group":"Lycanthrope","source":"PFRPG Bestiary 2","description":"Weretigers in humanoid form have large eyes, long noses, and sharp cheekbones. Most have brown or red hair, though a few have white, black, or even blue-gray. Their movements appear careful yet casual, and a person observing one could easily assume he's watching a skilled pickpocket, graceful dancer, or sultry courtesan.\n\nWeretigers tend to be solitary creatures, only spending time with others of their kind when they feel the urge to breed. Evil weretigers enjoy the thrill of hunting intelligent prey.","ecology":"","habitat_society":"","gear":"studded leather, masterwork short sword, 2 masterwork daggers"},{"name":"Wikkawak","cr":4,"xp":1200,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["goblinoid"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 armor, +3 Dex, +3 natural","hp":39,"hd":"6d8+12","hdvalue":6,"fort":4,"ref":8,"will":3,"resists":[{"type":"cold","value":5}],"speed":[{"type":"land","speed":30}],"melee":"battleaxe +9 (1d8+7/x3)","ranged":"javelin +7 (1d6+5)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"quench"}]}],"strength":20,"dexterity":17,"constitution":15,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":4,"cmb":9,"cmd":22,"feats":[{"feat":"Martial Weapon Proficiency (battleaxe)"},{"feat":"Nimble Moves"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":11},{"skill":"Intimidate","value":11},{"skill":"Perception","value":11},{"skill":"Stealth","value":16},{"skill":"Survival","value":7}],"languages":["Common","Giant","Goblin"],"sq":[{"type":"thuggery"},{"type":"trackless step"}],"environments":["cold mountains"],"organizations":["solitary","pair","gang (3-6)","warband (7-12 plus 3 warriors of 1st level and 1 chieftain of 3rd-5th level)"],"treasure":"none","description_visual":"This thick-bodied, white-furred bugbear wears bearskins and carries an axe made of ice and bone.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Thuggery","kind":"Ex","details":"Intimidate and Perception are class skills for wikkawaks."}],"description":"The goblinoid race of bugbears infests all regions of the world, and these cruel creatures have adapted to the various climes where they make their homes. In the icy wastes, a race of albino bugbears called wikkawaks stalk the windswept glaciers and frozen mountaintops. Well adapted to the cold, wikkawaks are masters of stealth and arctic survival, and they have the ability to quell lanterns, torches, and campfires with a thought. Wikkawaks leave no trail in even the heaviest of snows, though salt sprinkled on snow can supposedly reveal a wikkawak's tracks. Of course, by the time one has discovered a wikkawak's trail, it could already be too late.\n\nLike most bugbears, wikkawaks normally lead a solitary existence, preying on isolated settlers and hunters like pale arctic serial killers. Their powerful noses can sniff out a humanoid or animal over great distances. The rank smell of fear is a powerful stimulant to wikkawaks, and an individual wikkawak hunter might stalk and terrorize a potential victim for several nights, \"steeping\" its prey in dread and terror before finally pouncing. Wikkawaks consider humanoid flesh a great delicacy, and one might freeze a dead humanoid in a remote area, only to return to its grisly cache again and again to savor the taste of the victim for weeks on end. Wikkawaks enjoy keeping mementos of their victims, and prefer fingers as trophies. Wikkawaks occasionally congregate in larger groups, either to find mates or to better terrorize a large settlement. Wikkawak pairings seldom last longer than a winter, and young wikkawaks are pushed out into the cold to fend for themselves as soon as they've grown their fur. Wikkawaks don't enjoy the company of other goblinoids, and are just as likely to kill and eat a tribe of snow goblins as they are to rule their lesser kin. A wikkawak is covered in a thick pelt of insulating white fur, and its beady eyes are a dead white color. A typical wikkawak stands just over 7 ft. tall and weighs around 450 pounds.","ecology":"","habitat_society":"","gear":"mwk studded leather armor, battleaxe, 3 javelins"},{"name":"Wyrmling Copper Dragon","cr":4,"xp":1200,"alignment":"CG","size":"Tiny","type":"dragon","subtypes":["earth"],"init":7,"senses":[{"type":"dragon senses"}],"ac":19,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+3 Dex, +4 natural, +2 size","hp":37,"hd":"5d12+5","hdvalue":5,"fort":5,"ref":7,"will":5,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":100,"maneuverability":"average"}],"speed_mod":"climb stone","melee":"bite +7 (1d4/19-20), 2 claws +7 (1d3)","space":"2-1/2 ft.","reach":"0 ft. (5 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"30-ft. line, DC 13, 2d6 acid"},{"type":"slow breath"}],"strength":11,"dexterity":16,"constitution":13,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":5,"cmb":6,"cmd":16,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":9},{"skill":"Craft (traps)","value":9},{"skill":"Fly","value":15},{"skill":"Perception","value":9},{"skill":"Perform (comedy)","value":6},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":19}],"languages":["Common","Draconic"],"environments":["warm hills"],"organizations":["solitary"],"treasure":"triple","description_visual":"Bright, shining copper scales run from the horn-crowned head to the ridged tail of this long-winged dragon.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Climb Stone","kind":"Ex","details":"A copper dragon can climb on stone surfaces as though using the spider climb spell."},{"type":"Slow Breath","kind":"Su","details":"Instead of a line of acid, a copper dragon can breathe a cone of slowing gas. Those in the cone must make a Fortitude save or be slowed (as per the spell slow for 1d6 rounds plus 1 round per age category of the dragon."}],"description":"This whimsical dragon spends most of its time in combat trying to annoy and frustrate its enemies.","ecology":"","habitat_society":""},{"name":"Wyrmling Green Dragon","cr":4,"xp":1200,"alignment":"LE","size":"Small","type":"dragon","subtypes":["air"],"init":2,"senses":[{"type":"dragon senses"}],"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+2 Dex, +4 natural, +1 size","hp":37,"hd":"5d12+5","hdvalue":5,"fort":5,"ref":6,"will":6,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"bite +7 (1d6+1), 2 claws +7 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. cone, DC 13, 2d6 acid"}],"strength":13,"dexterity":14,"constitution":13,"intelligence":10,"wisdom":11,"charisma":10,"baseatk":5,"cmb":5,"cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":12},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":14},{"skill":"Survival","value":8},{"skill":"Swim","value":17}],"languages":["Draconic"],"sq":[{"type":"water breathing"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"triple","description_visual":"Scales the color of emeralds armor this ferocious dragon. A single sharp horn protrudes from the end of its toothy snout.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Water Breathing","kind":"Ex","details":"A green dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."}],"description":"Green dragons dwell in the ancient forests of the world, prowling under towering canopies in search of prey. Of all the chromatic dragons, green dragons are perhaps the easiest to deal with diplomatically.","ecology":"","habitat_society":""},{"name":"Xocothian","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"outsider","subtypes":["air","extraplanar","water"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":33,"hd":"6d10","hdvalue":6,"fort":5,"ref":5,"will":5,"dr":"5/cold iron","sr":15,"speed":[{"type":"land","speed":30},{"type":"fly","speed":90,"maneuverability":"average"},{"type":"swim","speed":90}],"speed_mod":"speed burst 200 ft.","melee":"bite +7 (1d8+2), 2 wings +2 (1d6+1)","space":"10 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"alter winds"},{"spell":"know direction"},{"spell":"shocking grasp"}]},{"frequency":"1/day","spells":[{"spell":"dimension door","details":"self plus 50 lbs. of objects only"},{"spell":"hydraulic torrent"}]},{"frequency":"3/day","spells":[{"spell":"chill metal"},{"spell":"cure light wounds"},{"spell":"faerie fire"},{"spell":"obscuring mist"}]}],"strength":15,"dexterity":12,"constitution":11,"intelligence":10,"wisdom":11,"charisma":10,"baseatk":6,"cmb":9,"cmd":20,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":8},{"skill":"Handle Animal","value":9},{"skill":"Knowledge (nature)","value":9},{"skill":"Knowledge (religion)","value":9},{"skill":"Perception","value":9},{"skill":"Stealth","value":6},{"skill":"Swim","value":10}],"languages":["Druidic","Sylvan","speak with animals"],"sq":[{"type":"form of sea and sky"}],"environments":["any (Plane of Air)","any (Plane of Water)"],"organizations":["solitary","pair","school (3-5)"],"treasure":"standard","description_visual":"This serpentine mix of flying fish and great seabird rolls and twists like waves in an ocean storm.","source":"Inner Sea Gods","special_abilities":[{"type":"Form of Sea and Sky","kind":"Su","details":"Once per hour, a xocothian can transform itself into two Small elementals (one air and one water) for up to 7 minutes. These elementals appear in adjacent squares. Each have half of the xocothian's current hit points and share the same mind. They can reform into the xocothian as a standard action if they are adjacent to each other-the reformed xocothian's hit points are equal to the total of the two elementals' hit points. If either elemental is slain, the xocothian must use its standard action on its next turn to reform (treat a slain elemental's hit points as 0 when determining the reformed xocothian's total hit points)."},{"type":"Speed Burst","kind":"Ex","details":"A xocothian can fly or swim up to 200 ft. as a full-round action. When using this ability, it must move in a straight line. This doesn't provoke attacks of opportunity."}],"description":"A xocothian is a physical manifestation of Gozreh's dual nature and destructive power. As a creature that has a form mingling both fish and fowl, it's as at home in the water as it is in the air. A xocothian amuses itself by manipulating clouds-it can fly in a way that whips off portions of clouds, allowing the creature to sculpt the cloud into fantastic creations. When on the sea, the creature dives in and out of the waves in a way that looks almost like a massive skipping stone dipping below the waves with each strike and then erupting into the air in a spray of sea water.\n\nBlunt and impatient, xocothians aren't fond of nuanced manipulation or clever gambits when dealing with others. They prefer straightforward approaches to obstacles and problems, and always takes such a route unless impeded in some way.\n\nWhen on the Material Plane and not called into service by mortal worshipers of Gozreh, xocothians enjoy exploring the natural wonders of the world. They splash through the seas, and soar through the skies, keeping away from civilization on these travels. Sometimes when encountering mortals, the creatures hide themselves in obscuring mist, hoping to be mistaken as a cloud.\n\nWhen at sea, they sometimes surge past ships underwater or in the air to create confusion and panic. When feeling sociable, they chat with local animals and discuss matters of weather and migrations with members of Gozreh's faith and respectful druids of other religions. They grow outraged with mortals who poison or pollute water and even those who befoul the air with bad smells (such as by burning garbage, casting stinking cloud, or running a tannery). Although they don't need to eat, they sometimes choose to do so for pleasure, enjoying the sort of food that a carnivorous fish or bird would consume.\n\nAs enigmatic as its creator, a xocothian may refer to itself as \"I,\" \"we,\" \"she,\" \"he,\" \"it,\" or \"they,\" whether in one body or two.\n\nXocothians are about 8 ft. long and weigh around 650 pounds.","ecology":"","habitat_society":""},{"name":"Yeti","cr":4,"xp":1200,"alignment":"N","size":"Large","type":"monstrous humanoid","subtypes":["cold"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":45,"hd":"6d10+12","hdvalue":6,"fort":6,"ref":6,"will":6,"immunities":["cold"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":30}],"melee":"2 claws +9 (1d6+4 plus 1d6 cold)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"frightful gaze"},{"type":"rend","details":"2 claws, 1d6+6 plus 1d6 cold"}],"strength":19,"dexterity":12,"constitution":15,"intelligence":9,"wisdom":12,"charisma":10,"baseatk":6,"cmb":11,"cmd":22,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":21},{"skill":"Intimidate","value":9},{"skill":"Perception","value":10},{"skill":"Stealth","value":1,"special":"+9 in snow"}],"languages":["Aklo"],"environments":["cold mountains"],"organizations":["solitary","pair","tribe (3-8)"],"treasure":"standard","description_visual":"This creature stands like a man, yet is half again the height of most men and covered with a coat of thick white fur.","source":"PFRPG Bestiary","special_abilities":[{"type":"Cold","kind":"Su","details":"A yeti's body generates intense cold, dealing 1d6 points of cold damage to any creature that contacts it with a natural attack or unarmed strike, or whenever it hits a foe with its claws or rend attack."},{"type":"Frightful Gaze","kind":"Su","details":"Creatures within 30 ft. that meet a yeti's gaze must succeed on a DC 13 Will save or stand paralyzed in fear for 1 round. This is a mind-affecting fear paralysis effect. A creature that successfully saves cannot be affected again by the frightful gaze of that yeti for 1 day. The save DC is Charisma-based."}],"description":"Mysterious and rarely seen (save by victims), the yeti is a towering denizen of the loneliest and tallest mountain peaks. Those who dwell upon the lower reaches of such storied slopes whisper tales of \"abominable snowmen\" who come down from the heights to raid, taking livestock or even humans as prey and leaving behind only monstrous barefoot tracks in the bloodstained snow.\n\nAlthough yeti stories are accurate in their portrayals of fierce, stealthy, and immensely strong creatures, they are not when it comes to ascribing the yeti's temperament and source. They dwell in small tribes atop their distant mountains, where they are sheltered from contact with most other races. Those with violent or cruel natures are usually forced out of tribes to live lonely lives as exiles, and without the support of a tribe such yeti are often driven to raiding lowlander settlements, thus perpetuating the myth of the yeti as a demon made flesh.\n\nThe source of such cruel madness can often be traced to a singular source-proximity to strange, eldritch dimensions. The yetis' mountain lairs rise high in places where the boundaries between this world and others rasp thin. It is unclear if the yeti are invaders from these dimensions or Material Plane natives inf luenced by otherworldly realms, but it seems certain that whatever their origins, the yeti are no friends to those who dwell beyond, and may even act as guardians against intrusions from such strange worlds into the Material Plane.","ecology":"","habitat_society":""},{"name":"Yhohm","cr":4,"xp":1200,"alignment":"NG","size":"Tiny","type":"outsider","subtypes":["extraplanar","fire","good"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"detect poison"}],"auras":["shroud of flame (10 ft., DC 14, 10 rounds)"],"ac":18,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+2 Dex, +1 dodge, +3 natural, +2 size","hp":37,"hd":"5d10+10","hdvalue":5,"hp_mods":["regeneration 1 (cold or evil)"],"fort":6,"ref":3,"will":6,"save_mods":"+4 vs. poison","defensive_abilities":["self-resurrection"],"dr":"5/evil","immunities":["fire","petrification"],"resists":[{"type":"electricity","value":10}],"sr":15,"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 talons +9 (1d2 plus 1d6 fire), bite +9 (1d3 plus 1d6 fire)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"holy fire"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect poison"}]},{"frequency":"at-will","spells":[{"spell":"light"},{"spell":"purify food and drink"},{"spell":"stabilize"},{"spell":"virtue"}]},{"frequency":"1/day","spells":[{"spell":"dimension door","details":"self only"},{"spell":"lesser restoration"},{"spell":"see invisibiliity"}]},{"frequency":"3/day","spells":[{"spell":"cure light wounds"},{"spell":"daylight"},{"spell":"flaming sphere"}]}],"strength":10,"dexterity":15,"constitution":14,"intelligence":10,"wisdom":15,"charisma":14,"baseatk":5,"cmb":5,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":14},{"skill":"Heal","value":10},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":10},{"skill":"Perform (sing)","value":10},{"skill":"Stealth","value":18}],"languages":["Celestial"],"environments":["any (Nirvana)"],"organizations":["solitary","pair","flight (3-5)"],"treasure":"none","description_visual":"This beautiful dove is as bright as the sun and the size of an eagle, surrounded by an aura of blazing white flames.","source":"Inner Sea Gods","special_abilities":[{"type":"Holy Fire","kind":"Su","details":"Like a flame strike, half the fire damage from a yhohm's fire attacks is fire damage; the other half is divine power and isn't subject to fire immunity or resistance."},{"type":"Self-Resurrection","kind":"Su","details":"A slain yhohm remains dead for only 1d4 rounds unless its body is completely destroyed by an effect such as disintegrate. Otherwise, a fully healed yhohm emerges from the remains 1d4 rounds after death, as if brought back to life via resurrection. The yhohm gains 1 permanent negative level when this occurs. A yhohm can self-resurrect only once per year. If a yhohm dies a second time before that year passes, its death is permanent. A yhohm that dies within the area of a desecrate spell cannot self-resurrect until the desecrate effect ends, at which point the yhohm immediately resurrects. A yhohm brought back to life by other means never gains negative levels as a result."},{"type":"Shroud of Flame","kind":"Su","details":"A yhohm can cause its feathers to burst into fire as a free action. As long as its feathers are burning, it deals an additional 1d6 points of fire damage with each natural attack, and any creature within 5 ft. must attempt a DC 14 Reflex save each round or take 1d6 points of fire damage at the start of its turn. A creature that attacks the yhohm with a natural or non-reach melee weapon takes 1d6 points of fire damage (no save) with each successful hit. The save DC is Constitution-based."}],"description":"A yhohm is a spirit of holy fire that serves the Dawnf lower.\n\nAccording to the faithful, each time a phoenix is reborn, a portion of its soul incarnates in Nirvana as a yhohm.\n\nEternally young and obsessed with life, a yhohm is a creature of healing, joyful song, and cleansing fire.\n\nWhile far less intimidating and wise than true phoenixes, yhohms prove far more carefree, as though a great weight has been lifted from their souls. Despite that, many yhohms also harbor a deep sadness, as though they have left some great work undone.\n\nA yhohm looks like a white dove, but is as large as an eagle, with eyes like burning coals that shine with the light of the sun. The presence of evil fills it with righteous indignation. It doesn't need to eat, but enjoys the taste of roasted berries and nuts. A yhohm measures just under 2 ft. long and weighs about 4 pounds.","ecology":"","habitat_society":""},{"name":"Zentragt","cr":4,"xp":1200,"alignment":"CN","size":"Large","type":"outsider","subtypes":["chaotic","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+1 Dex, +9 natural, -1 size","hp":39,"hd":"6d10+6","hdvalue":6,"fort":6,"ref":3,"will":5,"dr":"5/lawful","immunities":["fear"],"resists":[{"type":"cold","value":5},{"type":"electricity","value":5},{"type":"fire","value":5}],"sr":15,"speed":[{"type":"land","speed":30}],"melee":"bite +8 (1d6+3), 2 claws +9 (1d6+3 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"adamantine attacks"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"rage"}]},{"frequency":"3/day","spells":[{"spell":"bear's endurance"},{"spell":"cure light wounds"},{"spell":"true strike"}]}],"strength":17,"dexterity":12,"constitution":13,"intelligence":8,"wisdom":11,"charisma":10,"baseatk":6,"cmb":10,"cmb_special":"+4 vs. grapple, +2 vs. sunder","cmd":21,"cmd_special":"+2 vs. sunder, +4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Improved Sunder","type":"bonus"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Intimidate","value":9},{"skill":"Knowledge (planes)","value":5},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":9},{"skill":"Swim","value":16}],"languages":["Abyssal","Celestial","speak with animals (bears only)"],"sq":[{"type":"eat metal"}],"environments":["any (Elysium)"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"standard","description_visual":"This ferocious ursine brute has blade-like metallic teeth and appears to be covered in overlapping iron plates.","source":"Inner Sea Gods","special_abilities":[{"type":"Adamantine Attacks","kind":"Ex","details":"A zentragt's bite and claw attacks count as adamantine, chaotic, and magic for the purposes of overcoming damage reduction and bypassing hardness."},{"type":"Eat Metal","kind":"Su","details":"A zentragt can eat metal to heal itself. For every 5 pounds of iron or steel it consumes, it heals 5 hit points. Adamantine, cold iron, mithral, or metals with an enhancement bonus of +1 or higher heal it double this amount. It takes a zentragt 1 minute to eat 5 pounds of metal."}],"description":"Zentragts are armored, bearlike servitors of Gorum.\n\nTerse, burly, and independent, they are disciplined warriors, and use canny tactics whether alone, grouped with their own kind, or part of a legion of mixed creatures. They relish opportunities to charge into battle and eagerly serve in the vanguard of armies sworn to Our Lord in Iron.\n\nZentragts quickly grow bored if there isn'thing for them to fight, and challenge each other-or any creature present that looks like it can handle a rough fight-to maintain their high spirits. They work as needed to prepare for future battles, hauling materials to build defensive walls or siege engines for future conf licts or hunting creatures that consider themselves apex predators. They prefer using their magical abilities to enhance themselves and share their blessings with those they consider worthy allies. Some particularly brazen zentragts have even been known to use magic to enhance foes, bolstering their strength or healing their wounds to ensure a more worthy battle. Regardless of their foe, zentragts enjoy singing during combat (though they aren't particularly good at it), and keep rhythm by using their metallic natural weapons as percussive instruments against enemy armor.\n\nZentragts revere metal, seeing all iron and steel as a portion of their divine master. To them, the act of eating metal is a form of communion in which they replenish their bodies with Gorum's enduring substance. As such, they go out of their way to collect rare metals and treat such ritual meals with uncharacteristic respect.\n\nOn average, zentragts stand about 9 ft. tall and weigh over 1,200 pounds.","ecology":"","habitat_society":""},{"name":"Zuvembie","cr":4,"xp":1200,"alignment":"NE","size":"Medium","type":"undead","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 dodge, +2 natural","hp":37,"hd":"5d8+15","hdvalue":5,"fort":3,"ref":3,"will":6,"defensive_abilities":["channel resistance +4"],"dr":"5/piercing","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"battleaxe +4 (1d8+1/3), claw -1 (1d4) or 2 claws +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"corpse call","details":"DC 16"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"}]},{"frequency":"1/day","spells":[{"spell":"animate dead"},{"spell":"ray of exhaustion"},{"spell":"summon","details":"level 3, 1d3 bat or bird swarms [use the same stats], 1d2 constrictor snakes, 1d3 venomous snakes, or 1d4 wolves"}]},{"frequency":"3/day","spells":[{"spell":"ghoul touch"},{"spell":"scare"}]}],"strength":13,"dexterity":14,"intelligence":11,"wisdom":14,"charisma":15,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Ability Focus (corpse call)"},{"feat":"Dodge"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Knowledge (arcana)","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":14}],"languages":["Common (can't speak)"],"environments":["any land"],"organizations":["solitary"],"treasure":"standard (battleaxe)","description_visual":"This withered old corpse has a feral glint in her eyes and clasps a rusty axe in her yellow-nailed hands.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Corpse Call","kind":"Su","details":"Zuvembies cannot speak, but their strange calls and whistles captivate the minds of those who hear them. Once per day, a zuvembie may call out, and all living creatures with an Intelligence score of 3 or higher within a 100-foot spread must succeed at a DC 16 Will save or move toward the zuvembie using the most direct means possible. If this path leads them into a dangerous area such as through fire or off a cliff, the creatures receive a second saving throw to end the effect before moving into peril. Captivated creatures can take no actions other than to defend themselves. A victim within 5 ft. of the zuvembie simply stands and offers no resistance to the zuvembie's attacks. This effect continues for as long as the zuvembie continues its call as a standard action each round. This is a sonic mind-affecting charm effect, and has no effect on deaf creatures. The save DC is Charisma-based."}],"description":"Tied to the dark forces of nature and unholy magic, zuvembies employ fear and the wild creatures of the land to take their vengeance upon the living. Zuvembies appear to be withered, animate corpses but possess ruthless minds and blasphemous vigor. Revenge fuels a zuvembie, a hatefulness directed toward those who wronged it in life. Yet even when the last one who maligned it lies dead, its rage remains, turning against all who live, especially the relatives of the target of its original hate.\n\nMost zuvembies willingly performed the vile rituals to attain vengeance through unlife, but the transformation can also be wrought upon a helpless victim. The method of transforming into a zuvembie involves the creation and consumption of a vial of oil of animate dead, plus the performance of additional dark rites that take a day to perform and cost 3,000 gp. The ritual kills the target, who must make a DC 20 Will save. Failure results in the victim's death, while success means it reanimates as a free-willed zuvembie.\n\nZuvembies stand between 5 and 6 ft. tall and rarely weigh over 100 pounds.","ecology":"","habitat_society":""},{"name":"Achaierai","cr":5,"xp":1600,"alignment":"LE","size":"Large","type":"outsider","subtypes":["evil","extraplanar","lawful"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+1 Dex, +1 dodge, +9 natural, -1 size","hp":52,"hd":"7d10+14","hdvalue":7,"fort":7,"ref":6,"will":4,"sr":20,"speed":[{"type":"land","speed":50}],"melee":"bite +10 (2d6+4), 2 claws +10 (1d6+4)","space":"10 ft.","reach":"10 ft. with claw","special_attacks":[{"type":"black cloud"}],"strength":19,"dexterity":13,"constitution":14,"intelligence":11,"wisdom":14,"charisma":16,"baseatk":7,"cmb":12,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spring Attack"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+19 jump"},{"skill":"Climb","value":14},{"skill":"Fly","value":0},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":7},{"skill":"Swim","value":14}],"languages":["Infernal"],"environments":["any land (Hell)"],"organizations":["solitary","flock (5-8)"],"treasure":"standard","description_visual":"This bird-like beast is mostly head, lunging forward on four scaly legs. Wisps of noxious black vapor trail from its hooked beak.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Black Cloud","kind":"Su","details":"An achaierai can exhale a cloud of choking, toxic smoke three times per day. All creatures within 10 ft. of the achaierai immediately take 2d6 points of damage as their flesh melts and rots away. The cloud erodes sanity as well as flesh, and anyone who takes damage from the black cloud must also make a DC 15 Fortitude save or become confused. Every round, the victim may attempt another DC 15 Fortitude save to recover from the confusion; otherwise it persists, lasting indefinitely until the condition is removed or the victim eventually makes her saving throw. The confusion element of a black cloud is a mind-affecting effect. The save DC is Constitution-based. This is a poison effect. Achaierais are immune to this ability."}],"description":"An achaierai is a predator and scavenger of the lower planes that looks like a 15-foot-tall flightless bird, though its head and body are fused into one large unit, with four legs and atrophied wings. The thick, oily plumage covering its body all but conceals these tiny wings. An adult achaierai weighs roughly 750 pounds.\n\nThough not devils themselves, achaierais live and hunt on the scorched and blasted plains of Hell, where they make excellent use of their long, stilt-like legs in running down any lost souls or lesser devils who stumble into their feeding grounds. Once it has closed with its target, an achaierai attacks with its two front legs, punching or slashing, as well as biting with its powerful beak.\n\nFar smarter than their animalistic form might suggest, achaierais prefer to hunt in shrieking packs and use their prey's confusion and their own reach to their advantage, circling their quarry and darting in to attack as soon as the victim becomes distracted, then retreating again before the prey has a chance to retaliate. They have been known to wander through battlefields in the lower planes, picking over dying and regenerating creatures and souls, which has earned them the nickname \"Hell's vultures.\" As achaierais are immune to the toxic clouds of others of their kind, they often work in conjunction to use these clouds to herd or scatter enemies, form long lines of black clouds to protect their retreat, or merely panic opponents in large melees. Achaierais are fond of disemboweling their targets and feasting on the hot entrails while their mortally wounded prey screams itself to death. Of course, as outsiders, achaierais have no need to eat, and their elaborate hunting routines are simply the bird-beasts' sick form of entertainment.","ecology":"","habitat_society":""},{"name":"Andrazku","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","cold","demon","evil","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":57,"hd":"6d10+24","hdvalue":6,"fort":9,"ref":6,"will":2,"dr":"5/cold iron or good","immunities":["cold","electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"fire","value":10}],"sr":16,"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"2 slams +10 (1d6+4), bite +10 (1d6+4 plus bleed and 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d4"},{"type":"breath weapon","details":"10-ft. cone, 3d6 cold, Reflex half DC 17, usable every 1d4 rounds"},{"type":"mutilating gouge"},{"type":"powerful charge","details":"slam, 2d6+6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"righteous might"},{"spell":"summon","details":"level 3, 1 andrazku 25%"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"},{"spell":"locate creature"},{"spell":"teleport","details":"self plus 50 lbs. of objects only"}]}],"strength":21,"dexterity":13,"constitution":18,"intelligence":10,"wisdom":11,"charisma":14,"baseatk":6,"cmb":11,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Bluff","value":11},{"skill":"Climb","value":12},{"skill":"Intimidate","value":8},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":9},{"skill":"Survival","value":6},{"skill":"Swim","value":10}],"languages":["Abyssal","Giant","telepathy 100 ft."],"sq":[{"type":"icewalking"}],"environments":["any (Abyss)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"standard","description_visual":"This burly, primitive-looking creature has an ape-like upper body, demonic horns, cloven hooves, and skin the color of a snow-buried corpse.","group":"Demon","source":"AP 69","special_abilities":[{"type":"Icewalking","kind":"Ex","details":"This ability works like the spider climb spell, but the surfaces the demon climbs must be icy. The demon can move across icy surfaces without penalty and doesn't need to attempt Acrobatics checks to run or charge on ice."},{"type":"Mutilating Gouge","kind":"Ex","details":"If the andrazku hits with both slams in the same round, its target must succeed at a DC 17 Fortitude save or take 1 point of Charisma damage. The DC is Constitution-based."}],"description":"Andrazkus are thugs who use their strength to lord over weaker creatures. Their hatred is cold and seething, prone to suddenly snapping in an avalanche of ice and crushing blows. Birthed from the protomatter of the Abyss with natural gifts for tracking and subduing prey, they are sometimes used as trackers and jailors by more powerful demons who need to find lost prisoners and slaves.\n\nFrom the waist up these demons are built much like strong, hairy humans or dwarves, but with exaggerated proportions resembling those of a gorilla. Their thick necks sport bristling manes that merge with the hair on their backs, and their flat faces bear two ramlike horns and cold eyes filled with hate. Their breath is a freezing fog, and their teeth are small but numerous, like a shark's. An andrazku's legs seem small in comparison to its torso, bend backward like a satyr's, and end in large cloven hooves. Their skin is the dead blue of a frozen corpse or a frost giant. Their top-heavy builds mean they have difficulty standing upright and normally assume a hunched posture; many prefer to walk and run on all fours, like apes. An andrazku is 7 ft. tall at the shoulder and weighs 450 pounds.\n\nEcology\n\nAn andrazku forms from the soul of a chaotic mortal who hated women and used his or her power to oppress and demean them, such as a tyrant who selectively enforced laws against women, a priest who preached that women are the source of all sin, or a father who secretly beat his wives and daughters for their supposed failures. For this reason andrazkus are known to scholars as \"misogyny demons.\" Few of these souls dared to greater crimes (which would cause their souls to become incubi or babaus), nor were they once mortals who hated women but never acted upon their hatred-an andrazku only forms from a soul filled with sufficient hatred toward women to provoke action, but that is hampered by enough cowardice to prevent it from performing acts of greater evil. Most of them were male mortals, but an especially misogynistic evil female creature might become an andrazku in the Abyss.\n\nAn andrazku grows excited when it senses its prey's fear, but becomes frustrated if the hunt lasts for too long. Despite these demons' masculine appearance and aggression, most of them are impotent and some completely lack genitalia, rendering their lust pointless. Their nature is to berate, degrade, and beat; they tend to kill only when they feel an urge to eat, when their stymied passion becomes too great to tolerate, or when they are mocked for their shortcomings.\n\nAn andrazku prefers to attack with its bite and fists (often contemptuously slapping foes, minions, and prey with an open hand), but a vicious one may use a scourge and jagged-bladed sword as if pretending to be a balor. Sadistic and cruel, andrazkus have been known to chase down their prey, batter it for a while, and then release it, giving it enough of a head start that it thinks it has a chance of escaping. The andrazkus then track it down (using locate creature and teleport) to repeat the cycle again.\n\nAn andrazku in a position of authority likes to mark its minions and slaves with a scar on one side of the face indicating the demon's ownership. The demon typically uses its breath weapon to freeze a metal brand until it is cold enough to leave a permanent mark. If a slave is resistant or immune to cold, the demon uses a knife to carve its mark into one side of the creature's face.\n\nBecause of their long-simmering tempers and magical abilities, andrazkus are often called \"cold demons,\" and they mainly live in frigid Abyssal realms such as Jhuvumirak, home of demon lord Kostchtchie. Their intolerance of fire (despite their demonic resistance to it) and the cowardly nature of their origin-sin make them laughingstocks among demons (particularly babaus and incubi); as a result, andrazkus are sullen, resentful, and prone to take out their frustrations on weaker creatures- especially if said creatures are female.\n\nAndrazkus prefer to lair in ice caves or tunnels dug out of hard-packed snow. Some take advantage of their cold immunity and strong swimming ability to live in simple shelters on ice floes. An andrazku's hooves and huge hands allow it to cling to ice as though it were rough stone, preventing it from slipping and allowing it to use much of the vertical space in its lair to store treasure and observe intruders.\n\nHabitat & Society\n\nAndrazkus loathe associating with more powerful female demons in any way, and curse under their breath at mariliths and similar demons of great stature. Among female demons of similar power, they are quick with clever words, believable boasts, and secret confessions of desire, but these are all lies to disguise the hatred crackling beneath the surface. If given the opportunity, an andrazku would capture and torture a succubus merely because she is female (though a succubus is physically more powerful than a lone misogyny demon, and the hairy brutes have to gang up to have any chance of defeating a \"weakling\" succubus). Succubi and mariliths are aware of these simple-minded feelings held by andrazkus and they delight in tormenting the brutish creatures. Those female demons know they hold greater strength and power than andrazkus, and they enjoy lording over the creatures, even going so far as to kidnap them from time to time, bringing them to their own lairs and forcing the creatures into servitude.\n\nAndrazkus band together for strength, using their telepathy to silently coordinate their attacks. They often taunt their prey telepathically, either with words, promises of violence, or mocking laughter.\n\nWhen set loose on the Material Plane, an andrazku usually forces itself into a position of power over a humanoid tribe. Some ally with frost giant tribes, especially those who worship Kostchtchie. Duller ones find better company among girallons and dire apes.\n\nSummoning Andrazku\n\nAndrazkus are receptive to flattery about their size and strength. They like offers of weapons and strength-enhancing items as payment for their services. They can be assigned to guard, hunt, or retrieve; any Charisma check attempted as part a spell to convince an andrazku to undertake a mission other than these kinds of tasks takes a -2 penalty. A female summoner has a -10 penalty on all Charisma checks made to bargain unless the caster acts inferior and unworthy of the demon's aid.","ecology":"An andrazku forms from the soul of a chaotic mortal who hated women and used his or her power to oppress and demean them, such as a tyrant who selectively enforced laws against women, a priest who preached that women are the source of all sin, or a father who secretly beat his wives and daughters for their supposed failures. For this reason andrazkus are known to scholars as \"misogyny demons.\" Few of these souls dared to greater crimes (which would cause their souls to become incubi or babaus), nor were they once mortals who hated women but never acted upon their hatred-an andrazku only forms from a soul filled with sufficient hatred toward women to provoke action, but that is hampered by enough cowardice to prevent it from performing acts of greater evil. Most of them were male mortals, but an especially misogynistic evil female creature might become an andrazku in the Abyss.\n\nAn andrazku grows excited when it senses its prey's fear, but becomes frustrated if the hunt lasts for too long. Despite these demons' masculine appearance and aggression, most of them are impotent and some completely lack genitalia, rendering their lust pointless. Their nature is to berate, degrade, and beat; they tend to kill only when they feel an urge to eat, when their stymied passion becomes too great to tolerate, or when they are mocked for their shortcomings.\n\nAn andrazku prefers to attack with its bite and fists (often contemptuously slapping foes, minions, and prey with an open hand), but a vicious one may use a scourge and jagged-bladed sword as if pretending to be a balor. Sadistic and cruel, andrazkus have been known to chase down their prey, batter it for a while, and then release it, giving it enough of a head start that it thinks it has a chance of escaping. The andrazkus then track it down (using locate creature and teleport) to repeat the cycle again.\n\nAn andrazku in a position of authority likes to mark its minions and slaves with a scar on one side of the face indicating the demon's ownership. The demon typically uses its breath weapon to freeze a metal brand until it is cold enough to leave a permanent mark. If a slave is resistant or immune to cold, the demon uses a knife to carve its mark into one side of the creature's face.\n\nBecause of their long-simmering tempers and magical abilities, andrazkus are often called \"cold demons,\" and they mainly live in frigid Abyssal realms such as Jhuvumirak, home of demon lord Kostchtchie. Their intolerance of fire (despite their demonic resistance to it) and the cowardly nature of their origin-sin make them laughingstocks among demons (particularly babaus and incubi); as a result, andrazkus are sullen, resentful, and prone to take out their frustrations on weaker creatures- especially if said creatures are female.\n\nAndrazkus prefer to lair in ice caves or tunnels dug out of hard-packed snow. Some take advantage of their cold immunity and strong swimming ability to live in simple shelters on ice floes. An andrazku's hooves and huge hands allow it to cling to ice as though it were rough stone, preventing it from slipping and allowing it to use much of the vertical space in its lair to store treasure and observe intruders.","habitat_society":"Andrazkus loathe associating with more powerful female demons in any way, and curse under their breath at mariliths and similar demons of great stature. Among female demons of similar power, they are quick with clever words, believable boasts, and secret confessions of desire, but these are all lies to disguise the hatred crackling beneath the surface. If given the opportunity, an andrazku would capture and torture a succubus merely because she is female (though a succubus is physically more powerful than a lone misogyny demon, and the hairy brutes have to gang up to have any chance of defeating a \"weakling\" succubus). Succubi and mariliths are aware of these simple-minded feelings held by andrazkus and they delight in tormenting the brutish creatures. Those female demons know they hold greater strength and power than andrazkus, and they enjoy lording over the creatures, even going so far as to kidnap them from time to time, bringing them to their own lairs and forcing the creatures into servitude.\n\nAndrazkus band together for strength, using their telepathy to silently coordinate their attacks. They often taunt their prey telepathically, either with words, promises of violence, or mocking laughter.\n\nWhen set loose on the Material Plane, an andrazku usually forces itself into a position of power over a humanoid tribe. Some ally with frost giant tribes, especially those who worship Kostchtchie. Duller ones find better company among girallons and dire apes.\n\nSummoning Andrazku\n\nAndrazkus are receptive to flattery about their size and strength. They like offers of weapons and strength-enhancing items as payment for their services. They can be assigned to guard, hunt, or retrieve; any Charisma check attempted as part a spell to convince an andrazku to undertake a mission other than these kinds of tasks takes a -2 penalty. A female summoner has a -10 penalty on all Charisma checks made to bargain unless the caster acts inferior and unworthy of the demon's aid."},{"name":"Android Impostor","cr":5,"xp":1600,"race":"Android","classes":[{"class":"fighter","level":6}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["android"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+6 armor","hp":55,"hd":"6d10+18","hdvalue":6,"fort":8,"ref":3,"will":4,"save_mods":"Will: +2 vs. fear","defensive_abilities":["bravery +2","constructed"],"immunities":["disease","emotion-based effects","exhaustion","fatigue","fear","sleep"],"speed":[{"type":"land","speed":30}],"ranged":"mwk composite longbow +7 (1d8+3/3) or  throwing axe +7 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"nanite surge"},{"type":"weapon training","details":"axe +1"}],"strength":16,"dexterity":10,"constitution":14,"intelligence":12,"wisdom":13,"charisma":10,"baseatk":6,"cmb":9,"cmd":19,"feats":[{"feat":"Deceitful"},{"feat":"Improved Initiative"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (greataxe)"},{"feat":"Weapon Specialization (greataxe)"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Climb","value":4},{"skill":"Disguise","value":8},{"skill":"Intimidate","value":9},{"skill":"Perception","value":6},{"skill":"Sense Motive","value":-3},{"skill":"Survival","value":5},{"skill":"Swim","value":4}],"languages":["Common","Hallit"],"sq":[{"type":"armor training","details":"1"},{"type":"emotionless"}],"environments":["cold plains (Numeria)"],"organizations":["solitary"],"treasure":"none","description_visual":"Intricate tribal tattoos cover the skin of this greataxe-wielding Kellid warrior.","source":"Numeria Land Of Fallen Stars","special_abilities":[{"type":"Constructed","kind":"Ex","details":"For the purposes of effects that target a creature by type (such as a ranger's favored enemy or a bane weapon), androids count as both humanoids and constructs. Androids gain a +4 racial bonus on all saving throws against mind-affecting effects, paralysis, poison, and stun effects; they are not subject to fatigue or exhaustion, and are immune to disease, emotion-based effects, fear effects, and sleep effects. Androids can never gain morale bonuses."},{"type":"Emotionless","kind":"Ex","details":"Androids have problems processing emotions properly, and thus take a -4 penalty on Sense Motive checks."},{"type":"Nanite Surge","kind":"Ex","details":"An android's body is infused with nanites. Once per day as an immediate action, an android can cause his nanites to surge, granting the android a bonus equal to 3 + the android's character level on any one d20 roll; this ability must be activated before the roll is made. When an android uses this power, his circuitry-tattoos glow with light equivalent to that of a torch in illumination for 1 round."}],"description":"This android has managed to infiltrate a Kellid tribe, and impersonates a barbarian.\n\nIn battle, he feigns a berserker rage by using his martial skills and Power Attack. Intricate tribal tattoos obscure his circuitry-tattoos, and he takes care to never use his nanite surge in sight of others. Supplies from his disguise kit conceal his pale flesh and metallic irises, and because he knows that open wounds could expose him by revealing the pale color of his blood, he ensures the blood of his enemies coats him first.\n\nThe Kellid infiltrator has grown close to his tribe, especially his brothers and sisters in battle. He fears their hurt and rejection as much as their anger should they discover his secret. At the same time, he feels racial solidarity with fellow androids, and doesn't tolerate antagonism toward his kind. He may work to spread the message of acceptance of androids and other aliens among the generally superstitious and insular Kellids of Numeria.","ecology":"","habitat_society":"","gear":"potion of bull's strength, potions of cure light wounds [2], alchemist's fire [2], mwk chainmail, +1 greataxe, mwk composite longbow with 20 arrows, throwing axe, cloak of resistance +1, disguise kit, wooden holy symbol of Gorum, 130 gp"},{"name":"Angelic Guardian","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":53,"hd":"6d10+20","hdvalue":6,"fort":2,"ref":4,"will":2,"defensive_abilities":["deflective wings"],"dr":"5/adamantine","immunities":["construct traits","fire"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 slams +10 (1d6+4), 2 wings +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. line, 6d6 fire damage, Reflex DC 13 half, usable every 1d4 rounds"}],"strength":18,"dexterity":15,"wisdom":11,"charisma":1,"baseatk":6,"cmb":10,"cmd":22,"languages":["Common (cannot speak)"],"sq":[{"type":"metallic feathers"}],"environments":["any urban (Magnimar)"],"organizations":["solitary","assembly (2-4)","choir (5-8)"],"treasure":"none","description_visual":"This brass statue is sculpted in the shape of an angel with metal wings, and its halo takes the form of a burning crown.","source":"Magnimar City Of Monuments","special_abilities":[{"type":"Deflective Wings","kind":"Ex","details":"As a standard action, an angelic guardian can spread its wings and protect a single adjacent creature from the next ranged attack. The next time the protected creature would normally be hit with an attack from a ranged attack, the attack is instead deflected and the protected creature takes no damage. An angelic guardian can only deflect one ranged attack per turn in this way. This effect lasts until the angelic guardian's next turn or until the protected creature leaves its square, whichever comes first."},{"type":"Metallic Feathers","kind":"Ex","details":"An angelic guardian's wings are honed to razor-sharp edges, and attacks with them deal slashing damage instead of bludgeoning damage."}],"description":"Those toiling in the Golemworks of Magnimar provide myriad goods to their buyers, but perhaps none are so popular as the highly sought-after angelic guardian. Nobles, entrepreneurs, and wealthy paranoiacs alike purchase angelic guardians to serve as their personal protectors. Though inspired by Varisian depictions of angelic beings, these metallic beings are not truly from another plane, but are instead merely stylized automatons designed to watch over and protect their masters. They can be found throughout much of the Summit, where they line aristocrats' gardens and stand stoically for days or even weeks without moving, their burning halos the only feature suggestive of animation.\n\nAngelic guardians can be forged from various substances, though their bodies are typically made from brass and their wings from steel. Angelic guardians stand nearly 7 ft. tall and weigh 2,000 pounds.\n\nConstruction\n\nAn angelic guardian is made from 2,000 pounds of metal that is treated with unguents and ointments worth 2,000 gp.\n\nAngelic Guardian\n\nCL 9th; Price 22,000 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, mage armor, scorching ray, creator must be caster level 10th; Skill Craft (sculpture) or Knowledge (engineering) DC 15; Cost 12,000 gp","ecology":"","habitat_society":""},{"name":"Archelon","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"animal","init":5,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+10 armor, +1 Dex, -2 size, +0 natural","hp":59,"hd":"7d8+28","hdvalue":7,"fort":9,"ref":6,"will":5,"speed":[{"type":"land","speed":15},{"type":"swim","speed":50}],"melee":"bite +10 (2d8+9)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"capsize","details":"DC 25"}],"strength":22,"dexterity":13,"constitution":19,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":5,"cmb":13,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lunge"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Swim","value":18}],"sq":[{"type":"hold breath"}],"environments":["any coastlines","temperate water","warm water"],"organizations":["solitary","bale (2-6)"],"treasure":"none","description_visual":"The shell of this immense sea turtle easily spans 12 ft. in length. Its narrow head ends in a hooked beak.","group":"Megafauna","source":"PFRPG Bestiary 3","description":"An ancient relative of the smaller leatherback sea turtle, the archelon can grow up to 13 ft. long and 16 ft. from flipper to flipper. Weighing as much as 5,000 pounds, the archelon has an exceedingly powerful bite, and doesn't hesitate to use it to deter aquatic nuisances.\n\nLike other sea turtles, female archelons come ashore to lay and bury their eggs in sandy beaches, preferably facing deep water and without coral reefs. Once done, they return to the sea, leaving their eggs defenseless.\n\nThese creatures are often used by coastal tribes as guardians and escorts from island to island. Aquatic creatures, particularly locathah, often use them as beasts of burden, but their relatively slow swim speed makes them poor mounts.","ecology":"","habitat_society":""},{"name":"Army Ant Swarm","cr":5,"xp":1600,"alignment":"N","size":"Fine","type":"vermin","subtypes":["swarm"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":20,"ac_touch":20,"ac_flat_footed":18,"ac_mods":"+8 size, +2 Dex","hp":49,"hd":"11d8","hdvalue":11,"fort":7,"ref":5,"will":3,"defensive_abilities":["swarm traits"],"immunities":["weapon damage"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"swarm (3d6)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"cling"},{"type":"consume"},{"type":"distraction","details":"DC 15"}],"strength":1,"dexterity":15,"constitution":10,"wisdom":10,"charisma":2,"baseatk":8,"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":4}],"environments":["any tropical"],"organizations":["solitary","pair","patrol (3-6 swarms)","legion (7-16 swarms)"],"treasure":"none","description_visual":"A writhing carpet of ants seethes over the ground, consuming everything in its path.","group":"Army Ant","source":"PFRPG Bestiary","special_abilities":[{"type":"Cling","kind":"Ex","details":"If a creature leaves an army ant swarm's square, the swarm suffers 1d6 points of damage to reflect the loss of its numbers as several of the crawling pests continue to cling tenaciously to the victim. A creature with army ants clinging to him takes 3d6 points of damage at the end of his turn each round. As a full-round action, he can remove the ants with a DC 17 Reflex save. High wind or any amount of damage from an area effect destroys all clinging ants. The save DC is Dexterity-based."},{"type":"Consume","kind":"Ex","details":"An army ant swarm can rapidly consume any creature it swarms over. Against helpless or nauseated targets, an army ant swarm attack deals 6d6 points of damage."}],"description":"The notoriety of the army ant swarm is well earned. Constantly on the march, a hive of army ants is capable of eating anything that gets in the way of its unabating swath of destruction and ruin.","ecology":"","habitat_society":""},{"name":"Ascomoid","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"plant","init":1,"senses":[{"type":"tremorsense","modifier":"60 ft."}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":52,"hd":"7d8+21","hdvalue":7,"fort":8,"ref":3,"will":2,"dr":"10/piercing","immunities":["plant traits"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":40}],"melee":"slam +8 (2d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"spores"},{"type":"trample","details":"2d8+6, DC 17"}],"strength":18,"dexterity":13,"constitution":17,"wisdom":11,"charisma":1,"baseatk":5,"cmb":10,"cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Overrun","type":"bonus"}],"environments":["any underground"],"organizations":["solitary","cluster (2-8)"],"treasure":"none","description_visual":"This misshapen sphere of pale yellow-green fungus rolls with an unnerving speed, spewing clouds of foul spores as it advances.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Spores-inhaled; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d2 Str damage; cure 2 saves. The save DC is Constitution-based."},{"type":"Spores","kind":"Ex","details":"Once per round as a free action, an ascomoid can release a jet of deadly spores to a range of 30 ft. Upon impacting a solid surface, such as a wall or creature, the jet billows out into a cloud of spores that fills a 10-foot-radius spread. This cloud lasts for 1 round before dispersing. Any creature in the cloud must make a DC 16 Fortitude save or become nauseated as long as it remains in the cloud. Any creature that fails to save against this nausea is also exposed to the ascomoid's poison. The save DC is Constitution-based."}],"description":"Oversized fungi, ascomoids are frequently mistaken for giant puff balls until they begin to move, rolling toward any living prey that they sense. Once they have crushed the life out of a creature, they quickly move on, leaving spores behind in their victim's body to grow new ascomoids. Ascomoids can grow to a width of 10 ft., but they rarely weigh more than 400 pounds.\n\nWhile ascomoids require no light to grow, they do require a moist environment. They don't keep traditional lairs, but often wander the same areas over and over, littering these routes with the bones of past victims.\n\nAlthough they are typically solitary creatures, ascomoids dwelling in areas of ample moisture with generous sources of food-or frequent unwitting passersby- sometimes form deadly clusters. Such colonies of these giant fungi often lurk in large caverns among other pallid vegetation. Given ascomoids' ability to detect vibrations, the slightest quake or potential footfall sets them rolling, turning their cavernous lairs into churning meat grinders. Bounding about violently, groups of ascomoids sometimes take hours to settle back down, unable to distinguish between the movements of prey and the tumbling of their own kind. In some cases, ascomoids have been known to lair at the top of steep rises, crushing climbers as they roll in terrible fungal avalanches.\n\nThose crushed by an ascomoid or who fall victim to an ascomoid's spores face a revolting end, their bodies becoming hosts to quick-growing colonies of rampant fungi. Immature ascomoid mold sprouts quickly, typically appearing within 24 hours. After 48 hours, such victims become so overgrown with this furry, brown-green mold that they can no longer be restored to life by raise dead, as their bodies are too vitally pervaded and thoroughly consumed by the swiftly spreading mold. Within a month, a new ascomoid emerges from the foul mess.","ecology":"","habitat_society":""},{"name":"Basidirond","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"plant","init":1,"senses":[{"type":"low-light vision"},{"type":"tremorsense"}],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":52,"hd":"7d8+21","hdvalue":7,"fort":8,"ref":3,"will":1,"immunities":["cold","plant traits"],"weaknesses":["cold lethargy"],"speed":[{"type":"land","speed":20}],"melee":"slam +10 (1d8+7 plus spores)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hallucination cloud"},{"type":"spores"}],"strength":20,"dexterity":13,"constitution":16,"wisdom":11,"charisma":1,"baseatk":5,"cmb":7,"cmd":18,"environments":["any non-cold underground"],"organizations":["solitary","pair","grove (3-8)"],"treasure":"incidental","description_visual":"This strange plant consists of four spidery stalks, long green tendrils, and an inverted bell-shaped cap filled with spores.","source":"PFRPG Bestiary","special_abilities":[{"type":"Hallucination Cloud","kind":"Ex","details":"As a standard action once per minute, a basidirond can release a cloud of invisible spores in a 20-foot radius. All creatures within the area must succeed on a DC 16 Fortitude save or be affected by powerful hallucinations as long as they remain in the cloud plus 1d4 rounds after leaving the area. A new save must be made each round a creature remains within the affected area. A hallucination cloud persists for 5 rounds before dispersing-a strong wind causes it to disperse immediately. The save DC is Constitution-based. To determine what hallucination is suffered each round, roll 1d6 and consult the following table. d6 Hallucination 1 You're sinking in quicksand! Fall prone and spend 1 round flailing your arms and legs as if trying to swim. 2 Attacked by a swarm of spiders! Spend a full round action to attack the floor near you with your weapon. 3 An item you hold has turned into a viper! Drop it and flee from the item at top speed for 1 round. 4 You're suffocating! Stand in place, hold your breath, and clutch at your throat for 1 round. 5 You've shrunk to 1/10th your normal size! Take no actions for 1 round and monsters won't see you. 6 You're melting! Grasp hold of yourself in an attempt to hold yourself together, and take no actions for 1 round."},{"type":"Spores","kind":"Ex","details":"Any creature struck by a basidirond's slam attack is coated with spores. The creature struck must make a DC 16 Fortitude save or these spores take root in his flesh, and particularly in his lungs. The save DC is Constititonbased. Basidirond Spores: Disease-inhaled; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d2 Con damage; cure 1 save."},{"type":"Cold Lethargy","kind":"Ex","details":"Although a basidirond is immune to cold damage, any cold effect it is exposed to slows it for 1d4 rounds. During this time, the basidirond cannot use its hallucination cloud or spores."}],"description":"The strange fungal basidirond is a deadly plant monster that feeds on mineral-rich moisture, be it runoff from cave walls or fresh blood. By ensuring a constant flow of nutritious moisture, canny cave dwellers can use basidironds as guardians for their lairs, although they must take care to avoid the plant's hunting routes lest they become its latest victims.","ecology":"","habitat_society":""},{"name":"Basilisk","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"magical beast","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"-1 Dex, +8 natural","hp":52,"hd":"7d10+14","hdvalue":7,"fort":9,"ref":4,"will":5,"speed":[{"type":"land","speed":20}],"melee":"bite +10 (1d8+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"gaze"}],"strength":16,"dexterity":8,"constitution":15,"intelligence":2,"wisdom":13,"charisma":11,"baseatk":7,"cmb":10,"cmd":19,"cmd_special":"+12 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":10}],"environments":["any"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"incidental","description_visual":"This squat, reptilian monster has eight legs, bony spurs jutting from its back, and eyes that glow with pale green fire.","source":"PFRPG Bestiary","special_abilities":[{"type":"Gaze","kind":"Ex","details":"Turn to stone permanently (as flesh to stone), range 30 ft., Fortitude DC 15 negates. A creature petrified in this matter that is then coated (not just splashed) with fresh basilisk blood (taken from a basilisk no more than 1 hour dead) is instantly restored to flesh. A single basilisk contains enough blood to coat 1d3 Medium creatures in this manner. The save DC is Constitution-based."}],"description":"The basilisk, often called the \"King of Serpents,\" is in fact not a serpent at all, but rather an eight-legged reptile with a nasty disposition and the ability to turn creatures to stone with its gaze. Folklore holds that, much like the cockatrice, the first basilisks hatched from eggs laid by snakes and incubated by roosters, but little in the basilisk's physiology lends any credence to this claim.\n\nBasilisks live in nearly any terrestrial environment, from forest to desert, and their hides tend to match and ref lect their surroundings-a desert-dwelling basilisk might be tan or brown, while one that lives in a forest could be bright green. They tend to make their lairs in caves, burrows, or other sheltered areas, and these dens are often marked by statues of people and animals in lifelike poses-the petrified remains of those unfortunate enough to stumble across the basilisk.\n\nBasilisks have the ability to consume the creatures they petrify, their churning stomach acid dissolving and extracting nutrients from the stone, but the process is slow and inefficient, making them lazy and sluggish. As a result, basilisks rarely stalk prey or chase those who avoid their gaze, counting on their stealth and the element of surprise to keep them safe and fed. When not lying in wait for the small mammals, birds, and reptiles that normally make up their diet, basilisks spend their time sleeping in their lairs, and those brave enough to capture basilisks or hide treasure near them find that they make natural guardians and watchdogs.\n\nAn adult basilisk is 13 ft. long, with fully half of that made up by its long tail, and weighs 300 pounds. Some breeds have short, curved horns on their noses or small crests of bony growths topping their heads like crowns.\n\nThough normally solitary creatures, coming together only to mate and lay eggs, in particularly dangerous areas small groups may band together for protection and attack intruders en masse.\n\nFor unknown reasons, weasels and ferrets are immune to the basilisk's stare, and sometimes sneak into basilisk lairs while a parent is hunting in order to consume its young.\n\nSome legends suggest that a basilisk's blood can transmute common stones into other material, but this is likely a case of witnesses misinterpreting the magical restoration of previously petrified creatures or body parts.","ecology":"","habitat_society":""},{"name":"Bearded Devil","cr":5,"xp":1600,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +7 natural","hp":57,"hd":"6d10+24","hdvalue":6,"fort":9,"ref":7,"will":3,"dr":"5/good or silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":16,"speed":[{"type":"land","speed":40}],"melee":"glaive +11 melee (1d10+6 plus infernal wound) or 2  claws +10 melee (1d6+4)","space":"5 ft.","reach":"5 ft. (10 ft. with glaive)","special_attacks":[{"type":"beard"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 3, 1 bearded devil or 6 lemures, 50%"}]}],"strength":19,"dexterity":15,"constitution":19,"intelligence":6,"wisdom":12,"charisma":10,"baseatk":6,"cmb":10,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (glaive)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Intimidate","value":7},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":11}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","pair","squad (3-10)","troop (10-40)"],"treasure":"standard (glaive)","description_visual":"This seething devil deftly wields a vicious, saw-toothed glaive, while below its toothy maw writhes a hideous, twitching beard.","group":"Devil","source":"AP 36","special_abilities":[{"type":"Beard","kind":"Ex","details":"If a bearded devil hits a single opponent with both claw attacks, it also lashes at the same target with its spiky, filthy beard. The victim takes 1d8+2 points of damage and must succeed on a DC 17 Fortitude save or contract devil chills. The save DC is Constitution-based. Devil Chills: Disease-injury; save Fort DC 17; onset 1d4 days; frequency 1/day; effect 1d4 Str damage; cure 3 consecutive saves."},{"type":"Infernal Wound","kind":"Su","details":"The damage a bearded devil deals with its glaive inflicts persistent wounds that cause 2 points of bleed damage. Bleed caused from an infernal wound is particularly difficult to stanch-a DC 17 Heal check stops the damage, and any attempt to heal a creature suffering from an infernal wound must succeed on a DC 16 caster level check or the spell doesn't function. Success indicates the healing works normally and stops all bleed effects on the victim. The infernal wounds caused by a bearded devil are a supernatural ability of the devil, not of the weapon."}],"description":"Elite warriors in Hell's legions, bearded devils-or barbazus-fight savagely in the name of their infernal lords and command mindless hordes of the damned into battle. They collect and train with their infernally forged glaives among the vaults of Hell's third layer, Erebus, but inevitably return to the first layer, Avernus, to serve at the side of the dread lord Barbatos.\n\nBarbazus are fond of making charge attacks with their glaives, and try to maintain a 10-foot gap between themselves and their foes so they can use their signature polearms to great effect. Against a foe that has greater reach (or one able to otherwise avoid the devil's favored tactic), they drop their glaives and resort to their claws and hideous beards.\n\nAt attention, bearded devils stand over 6 ft. tall (though their squatting battle stances often make them appear shorter) and weigh upward of 200 pounds.","ecology":"","habitat_society":""},{"name":"Blackraven Scout","cr":5,"xp":1600,"race":"Human","classes":[{"class":"ranger","level":6}],"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["human"],"init":4,"ac":17,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+2 armor, +4 Dex, +1 dodge","hp":55,"hd":"6d10+18","hdvalue":6,"fort":8,"ref":10,"will":4,"speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +8 (1d8+1/x3)","ranged":"+1 composite longbow +12 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"giants +4, humans +2"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"animal messenger"},{"spell":"resist energy"}]}],"strength":12,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":6,"cmb":7,"cmd":22,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Improved Precise Shot"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Heal","value":10},{"skill":"Knowledge (local)","value":6},{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":10},{"skill":"Stealth","value":13},{"skill":"Survival","value":10}],"languages":["Common","Skald"],"sq":[{"type":"favored terrain","details":"cold +2"},{"type":"hunter's bond","details":"companions"},{"type":"track","details":"+3"},{"type":"wild empathy","details":"+5"}],"environments":["any (Hagreach)"],"organizations":["solitary","patrol (2-8)"],"treasure":"none","description_visual":"This tall, silent man wears a magnificent cloak of raven's feathers and a well-maintained suit of dark leather armor.","source":"Lands Of The Linnorm Kings","description":"The Blackravens are an elite band of soldiers and scouts who guard the eastern borders of the Linnorm Kingdoms against incursions from Irrisen and other threats, such as frost giants from the Stormspear Mountains and bands of ogres from the foothills that border the Nolands of Varisia. Freyr Darkwine, the castellan of Hagreach, leads the Blackravens, whose main headquarters is a granite fortress called Blackraven Hall, situated next to the Rimef low River near the border with Irrisen. While the Blackravens count among their number a wide range of individuals from varying races and classes, those most commonly encountered are scouts that patrol the rivers and roads throughout this borderland. These scouts undergo specific training against their hated enemies, and are all rangers specialized in fighting in subarctic conditions.\n\nA typical Blackraven patrol contains four to six members. In the open terrain around the Rimef low River, Blackraven patrols are sometimes mounted on horseback, but in less hospitable places they sometimes use dog sleds, skis, or snowshoes. They patrol the border regularly but in no set pattern, making it difficult to predict their movements.\n\nA Blackraven dons pale leather armor when he needs to blend into snowy environs, or when on reconnaissance missions into Irrisen. Blackraven scouts make extensive use of animal messenger spells to maintain communication over large areas. Specialists at battling trolls, Blackravens typically carry flaming arrows and alchemical fire to inhibit the creatures' regeneration and destroy their remains.","ecology":"","habitat_society":"","gear":"masterwork leather armor; +1 composite longbow with 20 arrows, 20 cold iron arrows, and 5 +1 flaming arrows; masterwork battleaxe; potions of cure moderate wounds [2]; acid [4]; alchemist's fire [4]; cloak of resistance +1; cold weather survival gear; other treasure"}];
